     1	import Image from 'next/image';
     2	import { isSafeImageUrl, rasterImageVariants } from '@/lib/utils';
     3	
     4	/*
     5	 * Team-member card. `member` shape (CMS):
     6	 * { initials, bg, name, role, bio, img, visible, order }.
     7	 *
     8	 * Photos render as <picture> with AVIF + WebP <source>s when the URL
     9	 * points at a same-origin raster (variants are generated at build time
    10	 * by frontend/scripts/build-images.mjs — PERF-05). Remote URLs (Unsplash
    11	 * etc.) fall back to next/image since we can't pre-generate variants for
    12	 * those. URLs go through isSafeImageUrl first to keep CMS-pasted strings
    13	 * from sneaking through as untrusted origins.
    14	 *
    15	 * The parent .team-photo has `position: relative; overflow: hidden` and
    16	 * `.team-photo-img` is styled `position: absolute; inset: 0; object-fit:
    17	 * cover` in globals.css — same shape as next/image's fill output, so
    18	 * either rendering path slots in identically.
    19	 */
    20	// eslint-disable-next-line @typescript-eslint/no-explicit-any
    21	interface TeamMember { initials?: string; bg?: string; name?: string; role?: string; bio?: string; img?: string; [key: string]: any }
    22	export default function TeamCard({ member }: { member?: TeamMember }) {
    23	  const { initials = 'TE', bg = 'bg-1', name = '', role = '', bio = '', img = '' } = member || {};
    24	  const safeImg = isSafeImageUrl(img) ? img : '';
    25	  const variants = safeImg ? rasterImageVariants(safeImg) : null;
    26	  return (
    27	    <div className="team-card">
    28	      <div className={`team-photo ${bg}${safeImg ? ' has-img' : ''}`}>
    29	        {safeImg && variants ? (
    30	          <picture>
    31	            <source type="image/avif" srcSet={variants.avif} />
    32	            <source type="image/webp" srcSet={variants.webp} />
    33	            <img
    34	              className="team-photo-img"
    35	              src={safeImg}
    36	              alt={`Portrait of ${name}`}
    37	              loading="lazy"
    38	              decoding="async"
    39	            />
    40	          </picture>
    41	        ) : safeImg ? (
    42	          <Image
    43	            className="team-photo-img"
    44	            src={safeImg}
    45	            alt={`Portrait of ${name}`}
    46	            fill
    47	            sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 25vw"
    48	          />
    49	        ) : null}
    50	        <span className="initials" aria-hidden={safeImg ? 'true' : 'false'}>{initials}</span>
    51	      </div>
    52	      <h4>{name}</h4>
    53	      <div className="role">{role}</div>
    54	      <p className="bio">{bio}</p>
    55	    </div>
    56	  );
    57	}

